import { Injectable, inject } from '@angular/core';
import { CarouselStore } from '../carousel.store';
import {
  AutoplayOptions,
  DEFAULT_AUTOPLAY_OPTIONS,
} from '../models/carousel.model';

// The callbacks to trigger actions in the carousel component
type AutoplayCallbacks = {
  slideToNext: () => void;
  autoplayStart: () => void;
  autoplayStop: () => void;
  autoplayPause: () => void;
};

@Injectable()
export class CarouselAutoplayService {
  private readonly store = inject(CarouselStore);

  private timer?: ReturnType<typeof setInterval>;
  private stopped = false;
  private autoplayTick = false;

  get isAutoplayTick(): boolean {
    return this.autoplayTick;
  }

  start(callbacks: AutoplayCallbacks): void {
    if (this.stopped) {
      return;
    }

    const autoplay = this.getAutoplayOptions();
    if (!autoplay) {
      return;
    }

    this.clearTimer();
    this.timer = setInterval(() => {
      this.autoplayTick = true;
      try {
        callbacks.slideToNext();
      } finally {
        this.autoplayTick = false;
      }
    }, autoplay.delay);
    callbacks.autoplayStart();
  }

  pauseOnHover(callbacks: Pick<AutoplayCallbacks, 'autoplayPause'>): void {
    const autoplay = this.getAutoplayOptions();
    if (!autoplay || !autoplay.pauseOnHover || !this.timer) {
      return;
    }

    this.clearTimer();
    callbacks.autoplayPause();
  }

  resumeOnMouseLeave(callbacks: AutoplayCallbacks): void {
    const autoplay = this.getAutoplayOptions();
    if (!autoplay || !autoplay.resumeOnMouseLeave || this.timer) {
      return;
    }

    this.start(callbacks);
  }

  stop(callbacks: Pick<AutoplayCallbacks, 'autoplayStop'>): void {
    this.clearTimer();
    callbacks.autoplayStop();
  }

  stopOnInteraction(callbacks: Pick<AutoplayCallbacks, 'autoplayStop'>): void {
    const autoplay = this.getAutoplayOptions();
    if (!autoplay || !autoplay.stopOnInteraction || this.stopped) {
      return;
    }

    this.stopped = true;
    this.stop(callbacks);
  }

  destroy(callbacks: Pick<AutoplayCallbacks, 'autoplayStop'>): void {
    this.stop(callbacks);
  }

  private clearTimer(): void {
    if (!this.timer) {
      return;
    }

    clearInterval(this.timer);
    this.timer = undefined;
  }

  private getAutoplayOptions(): AutoplayOptions | false {
    const autoplay = this.store.state().autoplay;
    if (!autoplay) {
      return false;
    }

    if (autoplay === true) {
      return DEFAULT_AUTOPLAY_OPTIONS;
    }

    return autoplay;
  }
}

import { Injectable, NgZone, inject } from '@angular/core';
import { DOCUMENT } from '@angular/common';
import { CarouselStore } from '../carousel.store';
import { Carousel } from '../models/carousel.model';
import { getFixedSlideSizeCss } from '../helpers/calculations.helper';

type CarouselBreakpoints = Record<string, Partial<Carousel>>;

@Injectable()
export class CarouselBreakpointService {
  private readonly store = inject(CarouselStore);
  private readonly ngZone = inject(NgZone);
  private readonly document = inject(DOCUMENT);
  private readonly window: Window | null = this.document?.defaultView ?? null;

  private mediaQueryListeners: {
    mql: MediaQueryList;
    listener: (e: MediaQueryListEvent) => void;
  }[] = [];

  /**
   * Generate CSS to apply breakpoints on SSR.
   */
  generateCss(
    breakpoints: CarouselBreakpoints | undefined,
    uniqueCarouselId: string
  ): string {
    if (!breakpoints || this.store.slidesPerView() === 'auto') {
      return '';
    }

    let css = '<style>';
    const baseSlidesPerView = this.store.slidesPerView() as number;
    const baseSpaceBetween = this.store.spaceBetween();

    Object.keys(breakpoints).forEach((query) => {
      // Validate media query contains only safe characters
      if (!/^[\w\s():\-,\.]+$/.test(query)) {
        console.warn('[Carousel] Invalid media query skipped:', query);
        return;
      }

      const config = breakpoints[query] ?? {};
      const slidesPerView: number =
        (typeof config.slidesPerView === 'number'
          ? config.slidesPerView
          : baseSlidesPerView) as number;
      const spaceBetween: number = config.spaceBetween ?? baseSpaceBetween;

      const columns = this.getGridColumnsValue(slidesPerView, spaceBetween);

      css += `
        @media ${query} {
          .slides.${uniqueCarouselId} {
            grid-auto-columns: ${columns} !important;
            gap: ${spaceBetween}px !important;
          }
        }
      `;
    });

    css += '</style>';
    return css;
  }

  /**
   * Create matchMedia listeners for each breakpoint.
   */
  setupMediaQueryListeners(
    breakpoints: CarouselBreakpoints | undefined,
    onMatch: (config: Partial<Carousel>) => void
  ): void {
    if (!this.window || !breakpoints) {
      return;
    }

    this.clear();

    Object.keys(breakpoints).forEach((query) => {
      const mql = this.window!.matchMedia(query);
      const config = breakpoints[query];

      const listener = (e: MediaQueryListEvent) => {
        this.ngZone.run(() => {
          if (e.matches) {
            onMatch(config);
          }
        });
      };

      mql.addEventListener('change', listener);
      this.mediaQueryListeners.push({ mql, listener });
    });
  }

  /**
   * Remove listeners.
   */
  clear(): void {
    this.mediaQueryListeners.forEach(({ mql, listener }) => {
      if (mql.removeEventListener) {
        mql.removeEventListener('change', listener);
      }
    });
    this.mediaQueryListeners = [];
  }

  private getGridColumnsValue(
    slidesPerView: number,
    spaceBetween: number
  ): string {
    return getFixedSlideSizeCss(slidesPerView, spaceBetween);
  }
}

import { inject, Injectable, Renderer2 } from '@angular/core';
import { CarouselStore } from '../carousel.store';

export const DEFAULT_IMAGES_TO_LOAD = 6;

@Injectable()
export class CarouselDomService {
  private store = inject(CarouselStore);
  constructor(private renderer: Renderer2) {}

  /**
   * Add class to identify slides roles and states.
   * @returns
   */
  updateSlides() {
    if (!this.store.allSlides()) {
      return;
    }

    const domSlides = this.store.domSlides();
    const slides =
      domSlides.length > 0
        ? domSlides
        : (this.store.slidesElements()?.map((slide) => slide.nativeElement) ??
          []);

    if (slides.length) {
      slides.forEach((slide: HTMLElement, index: number) => {
        const logicalIndex = this.getLogicalIndex(index);
        this.resetPositions(slide, logicalIndex);
        this.setPositionState(slide, logicalIndex);
        this.setAccessibility(slide, logicalIndex);
        this.setLazyLoading(slide, logicalIndex);
      });
    }
  }

  private setLazyLoading(slide: HTMLElement, index: number) {
    const state = this.store.state();

    if (!state.lazyLoading) {
      return;
    }

    const images = Array.from(slide.querySelectorAll('img'));
    if (!images?.length) {
      return;
    }

    const total = this.store.totalSlides();
    if (!total) {
      return;
    }

    const current = this.store.currentPosition();
    const loop = state.loop;
    const center = state.center;

    const slidesPerView = this.store.slidesPerView();
    const windowSize =
      typeof slidesPerView === 'number'
        ? Math.max(1, Math.ceil(slidesPerView))
        : DEFAULT_IMAGES_TO_LOAD;

    let isEager = false;

    if (!center) {
      if (!loop) {
        const minIndex = current;
        const maxIndex = Math.min(current + windowSize - 1, total - 1);
        isEager = index >= minIndex && index <= maxIndex;
      } else {
        const diff = (index - current + total) % total;
        isEager = diff >= 0 && diff <= windowSize - 1;
      }
    } else {
      const radius = Math.floor(windowSize / 2);
      let diff = Math.abs(index - current);

      if (loop) {
        diff = Math.min(diff, total - diff);
      }

      isEager = diff <= radius;
    }

    images.forEach((image) => {
      this.renderer.setProperty(image, 'loading', isEager ? 'eager' : 'lazy');
    });
  }

  private resetPositions(slide: HTMLElement, index: number) {
    // Remove any existing position-* class before setting the new one
    slide.classList.forEach((cls) => {
      if (cls.startsWith('position-')) {
        this.renderer.removeClass(slide, cls);
      }
    });
    this.renderer.removeClass(slide, 'prev');
    this.renderer.removeClass(slide, 'curr');
    this.renderer.removeClass(slide, 'next');
    this.renderer.addClass(slide, 'position-' + (index + 1));
  }

  private setPositionState(slide: HTMLElement, index: number) {
    const total = this.store.totalSlides();
    const current = this.store.currentPosition();
    if (!total || current < 0) {
      return;
    }

    if (index === current) {
      this.renderer.addClass(slide, 'curr');
      return;
    }

    const loop = this.store.loop();
    const previous = current > 0 ? current - 1 : loop ? total - 1 : -1;
    const next = current < total - 1 ? current + 1 : loop ? 0 : -1;

    if (index === previous) {
      this.renderer.addClass(slide, 'prev');
    }
    if (index === next) {
      this.renderer.addClass(slide, 'next');
    }
  }

  private setAccessibility(slide: HTMLElement, index: number) {
    this.renderer.setAttribute(slide, 'role', 'group');
    this.renderer.setAttribute(slide, 'aria-roledescription', 'slide');
    const total = this.store.totalSlides();
    this.renderer.setAttribute(
      slide,
      'aria-label',
      this.store.a11y().slideLabel?.({ index, total }) ??
        `${index + 1} of ${total}`,
    );
    this.renderer.setAttribute(
      slide,
      'tabindex',
      index === this.store.currentPosition() ? '0' : '-1',
    );
  }

  private getLogicalIndex(domIndex: number): number {
    if (this.store.virtual()) {
      return this.store.renderedIndices()?.[domIndex] ?? domIndex;
    }
    return this.store.slidesIndexOrder()?.[domIndex] ?? domIndex;
  }
}

import { inject, Injectable, Injector, signal, untracked } from '@angular/core';
import { CarouselStore } from '../carousel.store';
import { CarouselLoopService } from './carousel-loop.service';
import { CarouselPhysicsService } from './carousel-physics.service';
import { CarouselDomService } from './carousel-dom.service';
import {
  CAROUSEL_VIEW,
  CarouselViewActions,
} from '../components/carousel/view-adapter';
import { getPointerPosition } from '../helpers/event.helper';
import { CarouselVirtualService } from './carousel-virtual.service';
import { clampBetween } from '../helpers/calculations.helper';

export type PointerCoords = {
  x: number;
  y: number;
  isTouch: boolean;
};

export type DragState = {
  isDragging: boolean;
  hasMoved: boolean;
  hasExtraTranslation: boolean;
  lastMain: number;
  currentMain: number;
  lastMoveTime: number;
  lastClickTime: number;
  lastMainPosition: number;
  lockedAxis: 'main' | 'cross' | null;
};

// Determine threshold for mobile scroll on page while sliding.
const AXIS_LOCK_THRESHOLD_PX = 8;
const SWIPE_THRESHOLD_PX = 15;
const SWIPE_TIME_LIMIT_MS = 200;
const MIN_DRAG_DISTANCE_PX = 5;
const CLICK_MAX_DISTANCE_PX = 2;
const CLICK_MAX_TIME_MS = 200;

@Injectable()
export class CarouselInteractionService {
  private readonly store = inject(CarouselStore);
  private readonly physicsService = inject(CarouselPhysicsService);
  private readonly loopService = inject(CarouselLoopService);
  private readonly domService = inject(CarouselDomService);
  private readonly virtualService = inject(CarouselVirtualService);

  private readonly injector = inject(Injector);

  private suppressNextNativeClick = false;

  private get view(): CarouselViewActions {
    return this.injector.get(CAROUSEL_VIEW);
  }

  public sensitivity = 1;
  public velocitySensitivity = 5;
  public velocitySensitivityFreeMode = 1;
  public velocityBounds = 0.5;

  public gestureStart: {
    main: number;
    cross: number;
    time: number;
    event?: MouseEvent | TouchEvent;
  } = { main: 0, cross: 0, time: 0 };

  private dragState = signal<DragState>({
    isDragging: false,
    hasMoved: false,
    hasExtraTranslation: false,
    lastMain: 0,
    currentMain: 0,
    lastMoveTime: 0,
    lastClickTime: 0,
    lastMainPosition: 0,
    lockedAxis: null,
  });

  public getDragState() {
    return this.dragState();
  }

  public updateDragState(updatedState: Partial<DragState>) {
    this.dragState.update((state) => ({
      ...state,
      ...updatedState,
    }));
  }

  public consumeSuppressNextNativeClick(): boolean {
    if (!this.suppressNextNativeClick) {
      return false;
    }

    this.suppressNextNativeClick = false;
    return true;
  }

  /**
   * Update translation as user is dragging.
   * @param deltaMain
   * @param noExtraTranslation
   * @param mainPosition
   */
  public followUserMove(
    deltaMain: number,
    noExtraTranslation = false,
    mainPosition?: number,
  ) {
    const effectiveDeltaMain = this.store.isRtl() ? -deltaMain : deltaMain;

    let newTranslate =
      this.store.currentTranslate() + effectiveDeltaMain / this.sensitivity;
    const clampedTranslate = clampBetween(
      newTranslate,
      this.store.maxTranslate(),
      this.store.minTranslate(),
    );

    const isOutOfBounds =
      !this.store.loop() &&
      !Number.isNaN(newTranslate) &&
      newTranslate !== clampedTranslate;

    if (isOutOfBounds) {
      const resistance = this.store.resistance();
      let ratio: number;
      if (resistance === false || resistance === 0) {
        ratio = 0;
      } else if (resistance === true) {
        ratio = this.velocityBounds;
      } else {
        ratio = resistance;
      }

      if (noExtraTranslation || ratio <= 0) {
        // Hard clamp.
        newTranslate = clampedTranslate;
      } else {
        this.dragState.update((state) => ({
          ...state,
          hasExtraTranslation: true,
        }));
        newTranslate =
          this.store.currentTranslate() +
          (effectiveDeltaMain / this.sensitivity) * ratio;
      }
    } else {
      this.dragState.update((state) => ({
        ...state,
        hasExtraTranslation: false,
      }));
    }

    this.updatePositionOnMouseMove(newTranslate, mainPosition);
  }

  /**
   * Update current translate and apply transform CSS.
   * @param newTranslate
   * @param mainPosition
   */
  private updatePositionOnMouseMove(
    newTranslate: number,
    mainPosition?: number,
  ) {
    const rawVelocity = mainPosition
      ? (mainPosition - this.dragState().lastMainPosition) *
        (this.store.freeMode()
          ? this.velocitySensitivityFreeMode
          : this.velocitySensitivity)
      : 0;

    const velocity = this.store.isRtl() ? -rawVelocity : rawVelocity;

    this.store.patch({
      currentTranslate: newTranslate,
      velocity,
    });

    this.loopService.insertLoopSlidesByTranslation();
    this.virtualService.syncVirtualSlides();

    this.view.updateTransform();
  }

  /**
   * Promote the user-perceived index to currentRealPosition so the perception
   * persists once isDragging flips back to false. Used at drag end in
   * freeMode to avoid the active slide / thumb snapping back to
   * lastSlideAnchor after the user released the pointer in the residual zone.
   */
  private commitPerceivedIndex(explicit?: number) {
    const perceived = explicit ?? this.store.perceivedIndex();
    const real = this.store.currentRealPosition();
    if (perceived !== real && perceived >= 0) {
      this.store.patch({ currentRealPosition: perceived });
    }
  }

  public resetDrag() {
    this.dragState.update((state) => ({
      ...state,
      isDragging: false,
      hasMoved: false,
      lockedAxis: null,
    }));
    this.store.patch({ isDragging: false });
    this.domService.updateSlides();
  }

  private shouldStartDrag(event: MouseEvent | TouchEvent): boolean {
    if (!this.store.draggable()) {
      return false;
    }

    const target = event.target as HTMLElement | null;
    if (!target) {
      return true;
    }

    const selector = this.store.state().dragIgnoreSelector;
    if (!selector) {
      return true;
    }

    try {
      const ignoreCandidate = target.closest(selector);
      return !ignoreCandidate;
    } catch (e) {
      console.error('[Carousel] Invalid dragIgnoreSelector:', selector, e);
      return true;
    }
  }

  public handleMove(event: MouseEvent | TouchEvent, onDragStart?: () => void) {
    const dragState = this.getDragState();

    if (!dragState.isDragging) {
      return;
    }

    const { x, y, isTouch } = getPointerPosition(event);
    const main = this.store.axisConf().pointerMainPos({ x, y });
    const cross = this.store.axisConf().pointerCrossPos({ x, y });

    const now = Date.now();
    const gestureStart = this.gestureStart;
    if (isTouch && gestureStart) {
      const { lockedAxis } = dragState;

      if (!lockedAxis) {
        const deltaMain = main - gestureStart.main;
        const deltaCross = cross - gestureStart.cross;
        const absDeltaMain = Math.abs(deltaMain);
        const absDeltaCross = Math.abs(deltaCross);

        // Too little gesture to decide.
        if (
          absDeltaMain < AXIS_LOCK_THRESHOLD_PX &&
          absDeltaCross < AXIS_LOCK_THRESHOLD_PX
        ) {
          return;
        }

        if (absDeltaMain >= absDeltaCross) {
          this.updateDragState({ lockedAxis: 'main' });
        } else {
          // Cross gesture => no drag
          this.resetDrag();
          return;
        }

        // Main gesture.
        this.updateDragState({ lockedAxis: 'main' });
      } else if (lockedAxis === 'cross') {
        return;
      }
    }

    // For mouse.
    if (!isTouch && dragState.lockedAxis !== 'main') {
      this.updateDragState({ lockedAxis: 'main' });
    }

    if (this.getDragState().lockedAxis !== 'main') {
      return;
    }

    if (isTouch) {
      event.preventDefault();
    }

    const deltaMain = (main - dragState.currentMain) * this.sensitivity;
    const currentState = this.getDragState();
    this.updateDragState({
      hasMoved: true,
      lastMoveTime: now,
      currentMain: currentState.currentMain + deltaMain,
      lastMainPosition:
        now - currentState.lastMoveTime > 50
          ? main
          : currentState.lastMainPosition,
    });

    if (this.shouldStartDrag(gestureStart.event ?? event)) {
      if (!currentState.hasMoved) {
        onDragStart?.();
      }
      this.followUserMove(deltaMain, false, main);
    }
  }

  public handleStart(event: MouseEvent | TouchEvent) {
    // If this start should trigger a drag (not on a dragIgnoreSelector
    // target), prevent the browser's native drag of <img>/<a> children
    if (
      event instanceof MouseEvent &&
      this.shouldStartDrag(event) &&
      event.cancelable !== false
    ) {
      event.preventDefault();
    }

    const position = getPointerPosition(event);

    const main = this.store.axisConf().pointerMainPos(position);
    const cross = this.store.axisConf().pointerCrossPos(position);

    this.gestureStart = {
      main,
      cross,
      time: Date.now(),
      event,
    };

    this.store.patch({ lastTranslate: this.store.currentTranslate() });

    this.updateDragState({
      isDragging: true,
      hasMoved: false,
      hasExtraTranslation: false,
      currentMain: main,
      lastMainPosition: main,
      lastClickTime: new Date().getTime(),
      lockedAxis: null,
    });
    this.store.patch({ isDragging: true });

    // Stop autoplay on interaction if option is enabled
    this.view.stopAutoplayOnInteraction();
  }

  /**
   * Returns true if it was a dragging move and false otherwise.
   * @param event
   * @returns
   */
  public handleEnd(event: MouseEvent | TouchEvent): boolean {
    if (!this.getDragState().isDragging) {
      return false;
    }

    const { x, y } = getPointerPosition(event);
    const main = this.store.axisConf().pointerMainPos({ x, y });

    const timeEnd = Date.now();

    const dist = main - this.gestureStart.main;
    const duration = timeEnd - this.gestureStart.time;
    const absDist = Math.abs(dist);

    if (
      absDist < MIN_DRAG_DISTANCE_PX &&
      !this.getDragState().hasExtraTranslation
    ) {
      this.resetDrag();
      return false;
    }

    if (this.store.draggable() && event instanceof MouseEvent) {
      this.suppressNextNativeClick = true;
    }

    const isSwipe =
      duration < SWIPE_TIME_LIMIT_MS && absDist > SWIPE_THRESHOLD_PX;

    // Freemode specific
    if (this.store.freeMode() || this.store.navigateSlideBySlide()) {
      if (isSwipe) {
        this.physicsService.applyInertia(undefined, (translate) => {
          this.view.updateTransform(translate);
        });
        this.commitPerceivedIndex();
        this.resetDrag();
        return true;
      }
      if (
        this.getDragState().hasExtraTranslation &&
        !this.store.navigateSlideBySlide()
      ) {
        const perceivedBefore = this.store.perceivedIndex();
        this.view.slideToNearest();
        this.commitPerceivedIndex(perceivedBefore);
        this.resetDrag();
        return true;
      }
      this.commitPerceivedIndex();
      this.resetDrag();
      return true;
    }

    const swipeToLeft = dist < 0;

    // Swipe
    if (isSwipe && this.store.canSwipe()) {
      if (!this.store.isRtl()) {
        swipeToLeft ? this.view.slideToNext() : this.view.slideToPrev();
      } else {
        swipeToLeft ? this.view.slideToPrev() : this.view.slideToNext();
      }
      this.resetDrag();
      return true;
    }

    // Classic translation
    if (this.store.draggable()) {
      this.view.slideToNearest();
      this.commitPerceivedIndex();
    }

    this.resetDrag();
    return true;
  }

  public handleClick(event: MouseEvent) {
    if (this.consumeSuppressNextNativeClick()) {
      return;
    }

    if (this.getDragState().hasMoved) {
      return;
    }

    const deltaMain =
      this.store.axisConf().mouseMainPos(event) - this.gestureStart.main;
    const deltaCross =
      this.store.axisConf().mouseCrossPos(event) - this.gestureStart.cross;
    const dist = Math.hypot(deltaMain, deltaCross);
    const dt = Date.now() - this.gestureStart.time;

    if (dist > CLICK_MAX_DISTANCE_PX || dt > CLICK_MAX_TIME_MS) {
      return;
    }

    this.view.clickOnSlide(event);
  }

  public handleWheel(event: WheelEvent) {
    const mouseWheel = this.store.state().mouseWheel;
    if (!mouseWheel) {
      return;
    }
    const wheelAllowed =
      mouseWheel === true ||
      (this.store.isVertical() && mouseWheel.vertical) ||
      (!this.store.isVertical() && mouseWheel.horizontal);
    if (!wheelAllowed) {
      return;
    }
    const delta = this.store.axisConf().wheelMainDelta(event);
    if (!delta) {
      return;
    }

    event.preventDefault();
    this.store.patch({
      lastTranslate: this.store.currentTranslate(),
    });
    const deltaMain = -delta * this.sensitivity;
    this.followUserMove(deltaMain, true);
  }
}

import { ElementRef, Injectable, inject } from '@angular/core';
import { CarouselStore } from '../carousel.store';
import { CarouselNavigationService } from './carousel-navigation.service';

// Callbacks to trigger actions from the carousel component
type KeyboardActions = {
  slideToNext: () => void;
  slideToPrev: () => void;
  slideTo: (index: number) => void;
  initTouched: () => void;
};

@Injectable()
export class CarouselKeyboardService {
  private readonly store = inject(CarouselStore);
  private readonly navigationService = inject(CarouselNavigationService);

  handleKeyDown(
    event: KeyboardEvent,
    keyboardNavigation: boolean,
    slides: ReadonlyArray<ElementRef<HTMLElement>>,
    actions: KeyboardActions,
    debug = false,
  ): void {
    if (!keyboardNavigation) {
      return;
    }

    const handled = this.handleNavigationKey(event, actions);

    if (!handled) {
      return;
    }

    this.focusCurrentSlide(slides, debug);
    event.preventDefault();
    actions.initTouched();
  }

  private handleNavigationKey(
    event: KeyboardEvent,
    actions: KeyboardActions,
  ): boolean {
    const isRtl = this.store.isRtl();

    if (this.store.isVertical()) {
      if (event.key === 'ArrowDown') {
        actions.slideToNext();
        return true;
      }
      if (event.key === 'ArrowUp') {
        actions.slideToPrev();
        return true;
      }
      return false;
    }

    if (
      (event.key === 'ArrowRight' && !isRtl) ||
      (event.key === 'ArrowLeft' && isRtl)
    ) {
      actions.slideToNext();
      return true;
    }

    if (
      (event.key === 'ArrowLeft' && !isRtl) ||
      (event.key === 'ArrowRight' && isRtl)
    ) {
      actions.slideToPrev();
      return true;
    }

    if (event.key === 'Home') {
      const firstEnabled =
        this.navigationService.findNextEnabledIndex(-1, +1) ?? 0;
      actions.slideTo(firstEnabled);
      return true;
    }

    if (event.key === 'End') {
      const lastIndex = this.store.totalSlides() - 1;
      const lastEnabled =
        this.navigationService.findNextEnabledIndex(0, -1) ?? lastIndex;
      actions.slideTo(lastEnabled);
      return true;
    }

    return false;
  }

  private focusCurrentSlide(
    slides: ReadonlyArray<ElementRef<HTMLElement>>,
    debug: boolean,
  ): void {
    const pos = this.store.currentPosition();

    if (!slides || pos < 0 || pos >= slides.length) {
      if (debug) {
        console.warn('[Carousel] Cannot focus slide at invalid position', pos);
      }
      return;
    }

    slides[pos]?.nativeElement.focus?.();
  }
}

import { ElementRef, Injectable } from '@angular/core';
import { CarouselStore } from '../carousel.store';
import { CarouselLoopService } from './carousel-loop.service';
import { CarouselVirtualService } from './carousel-virtual.service';
import { rafThrottle } from '../helpers/raf-throttle.helper';

@Injectable()
export class CarouselLayoutService {
  private containerResizeObserver?: ResizeObserver;
  private slideResizeObserver?: ResizeObserver;
  private resizeTimeout?: ReturnType<typeof setTimeout>;
  private lastResizeTime = 0;
  private readonly resizeThrottleMs = 250;

  constructor(
    private readonly store: CarouselStore,
    private readonly loopService: CarouselLoopService,
    private readonly virtualService: CarouselVirtualService,
  ) {}

  updateLayoutFromSlides(
    slidesEls: ReadonlyArray<ElementRef<HTMLElement>>,
  ): boolean {
    if (!slidesEls.length) {
      return false;
    }

    const firstSize = this.store
      .axisConf()
      .rectSize(slidesEls[0]?.nativeElement);
    if (!firstSize) {
      return false;
    }

    this.store.patch({
      slidesElements: [...slidesEls],
    });

    this.loopService.initializeLoopCenter();
    this.virtualService.initVirtualWindow();

    return true;
  }

  observeContainerResize(
    container: HTMLElement | undefined,
    refresh: () => void,
  ): void {
    if (!container || typeof ResizeObserver === 'undefined') {
      return;
    }

    this.containerResizeObserver = new ResizeObserver((entries) => {
      const now = Date.now();

      // Ignore resize events if last resize was too recent
      if (now - this.lastResizeTime < this.resizeThrottleMs) {
        return;
      }

      for (const entry of entries) {
        const newWidth = entry.contentRect.width;
        if (Math.abs(newWidth - this.store.fullWidth()) <= 1) {
          continue;
        }

        this.lastResizeTime = now;
        clearTimeout(this.resizeTimeout);
        this.resizeTimeout = setTimeout(() => {
          // Force a full slide-widths re-measure (covers cases where the
          // per-slide ResizeObserver doesn't fire
          this.store.bumpResizeTick();
          refresh();
        }, 120);
        break;
      }
    });

    this.containerResizeObserver.observe(container);
  }

  observeSlidesResize(
    slidesEls: ReadonlyArray<ElementRef<HTMLElement>>,
    canRefresh: () => boolean,
    refreshLayout: () => void,
  ): void {
    if (!slidesEls.length || typeof ResizeObserver === 'undefined') {
      return;
    }

    if (!this.slideResizeObserver) {
      const callback = rafThrottle(() => {
        if (canRefresh()) {
          refreshLayout();
        }
      });

      this.slideResizeObserver = new ResizeObserver(() => callback());
    }

    this.slideResizeObserver.disconnect();

    slidesEls.forEach((el) =>
      this.slideResizeObserver!.observe(el.nativeElement),
    );
  }

  disconnectObservers(): void {
    this.containerResizeObserver?.disconnect();
    this.slideResizeObserver?.disconnect();
    clearTimeout(this.resizeTimeout);
    this.resizeTimeout = undefined;
  }
}

import { inject, Injectable, Injector, Renderer2 } from '@angular/core';
import { CarouselStore } from '../carousel.store';
import {
  CAROUSEL_VIEW,
  CarouselViewActions,
} from '../components/carousel/view-adapter';
import { extractVisibleSlides } from '../helpers/calculations.helper';
import { CAROUSEL_SLIDE_CLASS, SnapDom } from '../models/carousel.model';
import { positiveModulo } from '../helpers/utils.helper';

@Injectable()
export class CarouselLoopService {
  private store = inject(CarouselStore);
  private renderer = inject(Renderer2);
  private injector = inject(Injector);

  private get view(): CarouselViewActions {
    return this.injector.get(CAROUSEL_VIEW);
  }

  private get firstVisibleSlide() {
    return this.store.visibleDom()?.[0];
  }
  private get lastVisibleSlide() {
    return this.store.visibleDom()?.[this.store.visibleDom().length - 1];
  }

  private insertElement(before = true) {
    const slides = this.store.domSlides();

    const container = this.store.allSlides()?.nativeElement;
    if (!container) {
      return undefined;
    }

    const indexToInsert = before ? this.store.totalSlides() - 1 : 0;
    const index = this.store.slidesIndexOrder()[indexToInsert];
    const width = this.store.slidesWidths()[index];
    const elementToInsert = slides[indexToInsert] as HTMLElement | undefined;

    if (!elementToInsert) {
      return undefined;
    }

    if (before) {
      const firstReal = container.querySelector(
        '.' + CAROUSEL_SLIDE_CLASS,
      ) as HTMLElement | null;
      if (!firstReal) {
        return undefined;
      }
      try {
        this.renderer.removeChild(container, elementToInsert);
      } catch (e) {
        // Element not in container, that's ok
        console.warn(
          '[Carousel] Element not in container during loop insertion',
          e,
        );
      }
      this.renderer.insertBefore(container, elementToInsert, firstReal);
    } else {
      this.renderer.appendChild(container, elementToInsert);
    }

    const slidesIndexOrder = this.store.slidesIndexOrder();

    const value = (
      before ? slidesIndexOrder.pop() : slidesIndexOrder.shift()
    ) as number;
    this.store.patch({
      slidesIndexOrder: before
        ? [value, ...slidesIndexOrder]
        : [...slidesIndexOrder, value],
    });

    const offset = before
      ? -this.store.slidesWidths()[value] - this.store.state().spaceBetween
      : this.store.slidesWidths()[value] + this.store.state().spaceBetween;

    this.applyTranslate(this.store.currentTranslate() + offset);

    this.store.patch({
      lastTranslate: this.store.lastTranslate() + offset,
    });

    return { width, offset };
  }

  /**
   * When moving slides manually.
   */
  public insertLoopSlidesByTranslation() {
    if (!this.isLooping()) {
      return;
    }

    const [leftEdge, rightEdge] = [
      this.store.currentTranslate(),
      this.store.currentTranslate() + this.store.scrollWidth(),
    ];

    const viewportWidth = this.store.fullWidth();

    const buffer = 50;

    if (leftEdge > -buffer) {
      this.insertElement(true);
    }

    if (rightEdge < viewportWidth + buffer) {
      this.insertElement(false);
    }
  }

  /**
   * By prev or next button. Handle stepslides.
   * @param before
   */
  public insertLoopSlidesByNavigation(before = true) {
    if (!this.isLooping()) {
      return;
    }

    const leftmostDom = this.firstVisibleSlide;
    const rightmostDom = this.lastVisibleSlide;
    const leftMostIndex = leftmostDom.domIndex;
    const rightMostIndex = rightmostDom.domIndex;
    const slidesAvailableBefore = leftMostIndex;
    const slidesAvailableAfter = this.store.totalSlides() - rightMostIndex - 1;

    if (
      before === true &&
      slidesAvailableBefore < this.store.state().stepSlides
    ) {
      const slidesToInsertBefore =
        this.store.state().stepSlides - slidesAvailableBefore;

      for (let i = 1; i <= slidesToInsertBefore; i++) {
        this.insertElement(before);
      }
    }
    if (
      before === false &&
      slidesAvailableAfter < this.store.state().stepSlides
    ) {
      const slidesToInsertAfter =
        this.store.state().stepSlides - slidesAvailableAfter;

      for (let i = 1; i <= slidesToInsertAfter; i++) {
        this.insertElement(before);
      }
    }
  }

  /**
   * Direct click on slide.
   * @param indexSlided
   */
  public insertLoopSlidesBySlidingTo(indexSlided: number) {
    if (!this.isLooping()) {
      return;
    }

    const state = this.store.state();
    const futureTranslate = this.store.slideTranslates()[indexSlided];
    const currentTranslate = this.store.currentTranslate();
    const translateDiff = currentTranslate - futureTranslate;

    if (Math.abs(translateDiff) < 1) {
      return;
    }

    const modifiedVisibleDoms = extractVisibleSlides(
      this.store.snapsDom(),
      currentTranslate,
      state.fullWidth,
      translateDiff,
      this.store.center(),
    );

    if (!modifiedVisibleDoms.length) {
      return;
    }

    const leftmostDom = modifiedVisibleDoms[0];
    const rightmostDom = modifiedVisibleDoms[modifiedVisibleDoms.length - 1];

    const leftEdge = leftmostDom.translate;
    const rightEdge = rightmostDom.translate + rightmostDom.width;
    const visibleSpan = Math.abs(rightEdge - leftEdge);

    const offset = state.fullWidth - visibleSpan;
    if (offset <= 0) {
      return;
    }

    const insertElement = (before = true) => {
      let mainOffset = offset;
      const firstInserted = this.insertElement(before);

      if (firstInserted) {
        mainOffset -= firstInserted.width + state.spaceBetween;

        let stop = false;
        while (mainOffset > 0 && !stop) {
          const inserted = this.insertElement(before);
          if (!inserted) {
            stop = true;
            continue;
          }
          mainOffset -= inserted.width + state.spaceBetween;
        }
      }
    };

    const shouldInsertBefore = leftmostDom.domIndex === 0;
    const shouldInsertAfter =
      rightmostDom.domIndex >= this.store.totalSlides() - 1;

    if (shouldInsertBefore) {
      insertElement(true);
    }

    if (shouldInsertAfter) {
      insertElement(false);
    }
  }

  private isLooping() {
    if (!this.store.loop()) {
      return false;
    }

    if (this.store.visibleDom().length === 0) {
      return false;
    }

    if (this.store.virtual()) {
      return false;
    }

    return true;
  }

  private forceReflow() {
    this.store.allSlides()?.nativeElement?.getBoundingClientRect?.();
  }

  private applyTranslate(translate: number) {
    this.view.disableTransition();
    this.view.updateTransform(translate, false, true, false);
    this.forceReflow();
  }

  /**
   * Pre-populates the DOM for loop mode on initialization.
   * This is crucial for modes like 'center' to work from the start,
   * by ensuring the initial slide has slides before it in the DOM.
   */
  public initializeLoopCenter(): void {
    const state = this.store.state();

    if (!this.store.loop() || !this.store.center()) {
      return;
    }

    const totalSlides = this.store.totalSlides();
    if (totalSlides === 0 || !state.allSlides) {
      return;
    }

    const initialSlideWidth =
      this.store.slidesWidths()[state.initialSlide] ?? 0;
    const spaceToFill =
      state.fullWidth / 2 - initialSlideWidth / 2 - state.marginStart;

    if (spaceToFill <= 0) {
      return;
    }

    let widthFilled = 0;
    let slidesInserted = 0;

    while (widthFilled < spaceToFill && slidesInserted < totalSlides - 1) {
      const inserted = this.insertElement(true);

      if (inserted) {
        widthFilled += inserted.width + state.spaceBetween;
      }
      slidesInserted++;
    }
  }
}

import { inject, Injectable } from '@angular/core';
import { CarouselStore } from '../carousel.store';
import { positiveModulo } from '../helpers/utils.helper';
import { CarouselLoopService } from './carousel-loop.service';
import { CarouselVirtualService } from './carousel-virtual.service';

@Injectable()
export class CarouselNavigationService {
  private readonly loopService = inject(CarouselLoopService);
  private readonly store = inject(CarouselStore);
  private readonly virtualService = inject(CarouselVirtualService);

  /**
   * Calculate new index after prev or next action.
   * @param isSlidingNext
   * @returns
   */
  public calculateNewPositionAfterNavigation(isSlidingNext = true) {
    if (this.store.navigateSlideBySlide()) {
      const newIndex = isSlidingNext
        ? this.store.currentRealPosition() + this.store.state().stepSlides
        : this.store.currentRealPosition() - this.store.state().stepSlides;

      if (this.store.rewind()) {
        return newIndex;
      }

      return Math.max(0, Math.min(newIndex, this.store.totalSlides() - 1));
    }

    const newIndex = isSlidingNext
      ? this.store.currentPosition() + this.store.state().stepSlides
      : this.store.currentPosition() - this.store.state().stepSlides;

    if (this.store.loop()) {
      return positiveModulo(newIndex, this.store.totalSlides());
    }

    if (this.store.rewind()) {
      return newIndex;
    }

    // Only clamp when there's no loop and no rewind (hard stop at bounds)
    return Math.max(
      this.store.firstSlideAnchor(),
      Math.min(newIndex, this.store.lastSlideAnchor()),
    );
  }

  public isSlideDisabled(index: number): boolean {
    const slidesInput = this.store.slides();
    if (slidesInput && slidesInput.length) {
      return !!slidesInput[index]?.disabled;
    }

    const projected = this.store.state().projectedSlides ?? [];
    if (projected.length) {
      return !!projected[index]?.slideDisabled();
    }

    return false;
  }

  /**
   * Get next activated index from given index in given direction.
   */
  public findNextEnabledIndex(from: number, direction: 1 | -1): number {
    const total = this.store.totalSlides();
    if (!total) return from;

    const canWrap = this.store.loop() || this.store.rewind();

    let index = from;
    for (let i = 0; i < total; i++) {
      const nextRaw = index + direction;
      if (!canWrap && (nextRaw < 0 || nextRaw >= total)) {
        return from;
      }
      index = positiveModulo(nextRaw, total);
      if (!this.isSlideDisabled(index)) {
        return index;
      }
    }

    return from;
  }

  public getNextIndex() {
    this.loopService.insertLoopSlidesByNavigation(false);
    this.virtualService.syncVirtualSlides();

    // Calculate where we WOULD go
    const newPosition = this.calculateNewPositionAfterNavigation(true);

    // Check if this would exceed the bounds and we should rewind
    if (this.store.rewind() && !this.store.loop()) {
      const wouldExceedEnd = newPosition > this.store.lastSlideAnchor();
      if (wouldExceedEnd) {
        // Rewind to firstSlideAnchor (which is 0 for normal mode, or floor(spv/2) for notCenterBounds)
        const rewindIndex = this.store.firstSlideAnchor();
        return this.isSlideDisabled(rewindIndex)
          ? this.findNextEnabledIndex(rewindIndex, +1)
          : rewindIndex;
      }
    }

    return this.isSlideDisabled(newPosition)
      ? this.findNextEnabledIndex(this.store.currentPosition(), +1)
      : newPosition;
  }

  public getPrevIndex() {
    this.loopService.insertLoopSlidesByNavigation(true);
    this.virtualService.syncVirtualSlides();

    let indexSlided = undefined;
    if (this.store.state().stepSlides > 1) {
      indexSlided =
        this.store.state().currentPosition -
        (this.store.state().stepSlides - 1) -
        1;
      indexSlided = positiveModulo(indexSlided, this.store.totalSlides());
    }

    const hasReachedStart = this.store.hasReachedStart();
    let newPosition: number | undefined = undefined;
    if (hasReachedStart && this.store.rewind()) {
      newPosition = this.store.lastSlideAnchor();
    } else {
      newPosition = this.calculateNewPositionAfterNavigation(false);
    }

    newPosition = this.isSlideDisabled(newPosition)
      ? this.findNextEnabledIndex(this.store.currentPosition(), -1)
      : newPosition;

    return newPosition;
  }
}

import { inject, Injectable, DestroyRef } from '@angular/core';
import { CarouselStore } from '../carousel.store';
import { clampBetween } from '../helpers/calculations.helper';

interface InertiaConfig {
  baseFriction: number;
  edgeFriction: number;
  minVelocity: number;
}

@Injectable()
export class CarouselPhysicsService {
  private readonly store = inject(CarouselStore);
  private readonly destroyRef = inject(DestroyRef);

  private animationFrameId?: number;

  private readonly DEFAULT_CONFIG: InertiaConfig = {
    baseFriction: 0.93,
    edgeFriction: 0.8,
    minVelocity: 0.5,
  };

  constructor() {
    this.destroyRef.onDestroy(() => this.cancel());
  }

  applyInertia(
    config: InertiaConfig = this.DEFAULT_CONFIG,
    onUpdate?: (translate: number) => void
  ) {
    this.cancel();

    const step = () => {
      const velocity = this.store.state().velocity;

      if (Math.abs(velocity) < config.minVelocity) {
        return;
      }

      const friction = this.isAtEdge()
        ? config.edgeFriction
        : config.baseFriction;
      const newVelocity = velocity * friction;
      const newTranslate = this.store.currentTranslate() + velocity;

      const clampedTranslate = clampBetween(
        newTranslate,
        this.store.state().maxTranslate,
        this.store.state().minTranslate
      );

      this.store.patch({
        currentTranslate: clampedTranslate,
        velocity: newVelocity,
      });

      onUpdate?.(clampedTranslate);

      this.animationFrameId = requestAnimationFrame(step);
    };

    this.animationFrameId = requestAnimationFrame(step);
  }

  cancel() {
    if (this.animationFrameId) {
      cancelAnimationFrame(this.animationFrameId);
      this.animationFrameId = undefined;
    }
  }

  private isAtEdge(): boolean {
    const translate = this.store.currentTranslate();
    return (
      translate <= this.store.state().maxTranslate ||
      translate >= this.store.state().minTranslate
    );
  }
}

import {
  computed,
  Injectable,
  signal,
  TemplateRef,
  WritableSignal,
} from '@angular/core';

@Injectable()
export class CarouselRegistryService {
  public carouselNavigationLeftSignal: WritableSignal<
    TemplateRef<any> | undefined
  > = signal(undefined);

  public carouselNavigationRightSignal: WritableSignal<
    TemplateRef<any> | undefined
  > = signal(undefined);

  private readonly externalControlsCount = signal(0);
  public readonly hasExternalControls = computed(
    () => this.externalControlsCount() > 0,
  );

  public registerExternalControl(): void {
    this.externalControlsCount.update((count) => count + 1);
  }

  public unregisterExternalControl(): void {
    this.externalControlsCount.update((count) => Math.max(0, count - 1));
  }
}

